class Demo {
  List items
  int index = 0

  void open() {
    items = [
      [name: 'zhang', age: 18],
      [name: 'li', age: 20],
      [name: 'wang', age: 22]
    ]
  }

  boolean pollNext(output) {
    if (index >= items.size()) {
      return false
    }
    output.collect(items[index++])
    return true
  }
}
